const sv = SugarCube.State.variables;
const results = [];
for (let v = 0; v <= 10; v++) {
  sv.player.arousal = v;
  SugarCube.Engine.show();
  // wait a tick then capture
  const wrapper = document.querySelector('.arousal-wrapper');
  if (wrapper) {
    const fill = wrapper.querySelector('.arousal-progress-fill');
    const text = wrapper.querySelector('.arousal-progress-text');
    results.push({
      arousal: v,
      fill_class: fill ? fill.className : null,
      fill_width: fill ? fill.style.width : null,
      text: text ? text.textContent : null,
    });
  } else {
    results.push({arousal: v, error: 'no wrapper'});
  }
}
return results;

const setup = window.setup || {};
const sugar = window.SugarCube;
const setupKeys = Object.keys(setup).filter(k => /arous|energ|update|refresh|render|sidebar/i.test(k));
return {setupKeys, sugar_setup_keys: Object.keys(sugar.setup || {}).filter(k => /arous|energ|update|refresh|render|sidebar/i.test(k))};

const S = window.SugarCube;
const out = {};
out.has_Story = !!S.Story;
if (S.Story) {
  out.passage_count = S.Story.passages ? Object.keys(S.Story.passages).length : 'no passages prop';
  // search passages for arousal-related text
  const passages = S.Story.passages || {};
  const arousalPassages = [];
  for (const name in passages) {
    const p = passages[name];
    const txt = p.text || p.source || '';
    if (/Calm|Aroused|Heated|Burning|arousal-progress|arousalText|player\.arousal/i.test(txt)) {
      arousalPassages.push({name, len: txt.length, tags: p.tags || []});
    }
  }
  out.matching_passages = arousalPassages.slice(0, 10);
}
return out;

const S = window.SugarCube;
return {
  Story_keys: Object.keys(S.Story || {}),
  Story_proto_keys: S.Story ? Object.keys(Object.getPrototypeOf(S.Story)) : null,
};

// search all scripts in the document for the band label strings
const scripts = Array.from(document.querySelectorAll('script'));
const bodies = scripts.map(s => s.textContent || '').filter(t => t.length > 50);
const out = [];
for (const body of bodies) {
  if (/Aroused|Calm.*Warm|Burning/i.test(body)) {
    const idx = body.search(/Calm|Aroused|Burning|Heated|Warm/i);
    out.push(body.slice(Math.max(0, idx-300), idx+800));
  }
}
return {scripts_count: scripts.length, big_scripts: bodies.length, found_excerpts: out.slice(0, 3)};

const scripts = Array.from(document.querySelectorAll('script'));
const bodies = scripts.map(s => s.textContent || '');
const out = [];
for (const body of bodies) {
  // find macro definitions related to arousal widget rendering
  const macroMatches = body.match(/Macro\.add\(['"](?:UpdateArousal|PlayerArousal|arousalText|arousalBar|RenderArousal|UpdateBar|arousalWrapper)['"][\s\S]{0,2400}?\}\);/g);
  if (macroMatches) out.push(...macroMatches);
  // also find any block referencing arousal-progress-fill class assignments
  const fillMatches = body.match(/arousal-progress-fill[\s\S]{0,1200}/g);
  if (fillMatches) out.push(...fillMatches);
}
return out.slice(0, 4);

const scripts = Array.from(document.querySelectorAll('script'));
const bodies = scripts.map(s => s.textContent || '');
for (const body of bodies) {
  const m = body.match(/Macro\.add\(['"]ArousalDisplay['"][\s\S]*?\n\}\);/);
  if (m) return m[0];
}
return 'not found';

const sv = SugarCube.State.variables;
const max = sv.game ? sv.game.maxArousal : '?';
const lbs = (typeof LeftBarService !== 'undefined') ? LeftBarService : null;
const bands = [];
if (lbs && lbs.getArousalText) {
  for (let i = 0; i <= 4; i++) bands.push({level: i, data: lbs.getArousalText(i)});
}
return {maxArousal: max, all_game_keys: Object.keys(sv.game||{}), bands};

const sv = SugarCube.State.variables;
const out = {maxArousal: sv.game && sv.game.maxArousal, has_LeftBarService_global: typeof window.LeftBarService};
// search scripts for getArousalText
const scripts = Array.from(document.querySelectorAll('script')).map(s => s.textContent || '');
for (const body of scripts) {
  const m = body.match(/getArousalText[\s\S]{0,1200}/);
  if (m) { out.getArousalText_src = m[0].slice(0,1200); break; }
}
return out;

const scripts = Array.from(document.querySelectorAll('script')).map(s => s.textContent || '');
const out = [];
for (const body of scripts) {
  // function definition (not call site)
  const defMatch = body.match(/getArousalText\s*[:=]\s*function[\s\S]{0,1500}/);
  if (defMatch) out.push({kind: 'function-def', src: defMatch[0].slice(0, 1500)});
  // class method
  const methodMatch = body.match(/getArousalText\s*\([^)]*\)\s*\{[\s\S]{0,1500}/);
  if (methodMatch) out.push({kind: 'method', src: methodMatch[0].slice(0, 1500)});
  // LeftBarService class declaration  
  const classMatch = body.match(/(class|function)\s+LeftBarService[\s\S]{0,3500}/);
  if (classMatch) out.push({kind: 'service-class', src: classMatch[0].slice(0, 3500)});
}
return out.slice(0, 3);

const sv = SugarCube.State.variables;
const Macro = SugarCube.Macro;
const arousalMacro = Macro.get('ArousalDisplay');
const results = [];
const samples = [0, 1, 3, 5, 7, 10];
const sandbox = document.createElement('div');
sandbox.id = 'arousal-sandbox';
sandbox.style.cssText = 'position:fixed;top:5px;right:5px;background:#222;padding:6px;z-index:99999;width:280px;';
document.body.appendChild(sandbox);
const orig = sv.player.arousal;
for (const v of samples) {
  sv.player.arousal = v;
  const slot = document.createElement('div');
  slot.style.cssText = 'background:#111;margin:4px;padding:6px;border:1px solid #444;';
  const lbl = document.createElement('div');
  lbl.textContent = 'arousal=' + v;
  lbl.style.cssText = 'color:#fff;font-size:11px;font-family:monospace;';
  slot.appendChild(lbl);
  sandbox.appendChild(slot);
  // call handler with output rerouted to slot
  arousalMacro.handler.call({output: slot, args: []});
  // extract structure
  const w = slot.querySelector('.arousal-wrapper');
  if (w) {
    const fill = w.querySelector('.arousal-progress-fill');
    const text = w.querySelector('.arousal-progress-text');
    results.push({
      arousal: v,
      fill_class: fill ? fill.className : null,
      fill_width: fill ? fill.style.width : null,
      text: text ? text.textContent : null,
    });
  }
}
sv.player.arousal = orig;
return results;

const s = document.getElementById('arousal-sandbox'); if (s) s.remove();
// find the caption-card that holds energy+arousal
const card = document.querySelector('.caption-card-body');
if (!card) return 'no card';
let parent = card.parentElement;
while (parent && !parent.querySelector('.caption-card-header, .card-header, [class*=card-title]')) parent = parent.parentElement;
const header = parent ? parent.querySelector('.caption-card-header, .card-header, [class*=card-title]') : null;
return {
  card_outer_html: (parent || card.parentElement).outerHTML.slice(0, 1500),
  card_text: (parent || card.parentElement).innerText.replace(/\s+/g,' ').trim(),
};

const wrappers = document.querySelectorAll('.energy-wrapper');
if (!wrappers.length) return 'no energy-wrapper';
const w = wrappers[0];
let card = w.closest('.caption-card');
return card ? {outer: card.outerHTML.slice(0, 2500), text: card.innerText.replace(/\s+/g,' ').trim()} : 'no caption-card ancestor';
